head.script:
scwin.onpageload = function () {

};

/**
 * @method
 * @name round
 * @description 반올림 처리를 한다.
 * @param {String|Number} value 반올림 처리를 할 값
 * @param {Number} point 반올림 처리를 할 소수점 자리 수 (Default : 0, 정수 값으로 반올림 처리)
 * @returns {Number} 반올림 처리를 한 숫자 값
 * @example
$c.num.round(23.4567); // return 예시) 23
$c.num.round(23.5567); // return 예시) 24
$c.num.round(23.5567, 2); // return 예시) 23.56
$c.num.round(23.5564, 3); // return 예시) 23.556

 * @hidden N
 * @exception 
 */
scwin.round = function (value, point) {
    let num = 1;
    if (typeof point !== "undefined") {
        num = Math.pow(10, point);
    }

    return Math.round(Number(value) * num) / num;
};


/**
 * @method
 * @name floor
 * @description 내림 처리를 한다.
 * @param {String|Number} value 내림 처리를 할 값
 * @param {Number} point 내림 처리를 할 소수점 자리 수 (Default : 0, 정수 값으로 내림 처리)
 * @returns {Number} 내림 처리를 한 숫자 값
 * @example
$c.num.floor(23.4567); // return 예시) 23
$c.num.floor(23.5567); // return 예시) 23
$c.num.floor(23.5567, 2); // return 예시) 23.55
$c.num.floor(23.5564, 3); // return 예시) 23.556
 * @hidden N
 * @exception 
 */
scwin.floor = function (value, point) {
    let num = 1;
    if (typeof point !== "undefined") {
        num = Math.pow(10, point);
    }

    return Math.floor(Number(value) * num) / num;
};


/**
 * @method
 * @name ceil
 * @description 올림 처리를 한다.
 * @param {String} value 올림 처리를 할 값 (String 또는 Number 타입 지원)
 * @param {Integer} point 올림 처리를 할 소수점 자리 수 (Default : 0, 정수 값으로 올림 처리)
 * @returns {Number} 올림 처리를 한 숫자 값
 * @example
$c.num.ceil(23.5567); // return 예시) 24
$c.num.ceil(23.5567, 2); // return 예시) 23.56
 * @hidden N
 * @exception 
 */
scwin.ceil = function (value, point) {
    let num = 1;
    if (typeof point !== "undefined") {
        num = Math.pow(10, point);
    }

    return Math.ceil(Number(value) * num) / num;
};

/**
 * @method
 * @name formatMoney
 * @description 세번째자리마다 콤마 표시, 금액, setDisplayFormat("#,###&#46##0", "fn_userFormatter2") - 입력된 str 포메터를 적용하여 반환
 * @param {String|Number} value 포멧터를 적용할 값
 * @param {String} type 적용할 포멧터 형식(Default:null,dollar,plusZero,won)
 * @returns {String} 포멧터가 적용된 문자열
 * @example
$c.num.formatMoney("12345"); // 12,345
$c.num.formatMoney("12345", "dollar"); // $12,345
$c.num.formatMoney("12345", "plusZero"); // 123,450
$c.num.formatMoney("12345", "won"); // 12,345원
 * @hidden N
 * @exception 
 */
scwin.formatMoney = function (value, type) {
    // 숫자로 변환 불가하면 원본 반환
    if (isNaN(Number(value))) {
        return value;
    }

    const negativeSe = Number(value) < 0;
    let amount = new String(value).trim() + (type == "plusZero" ? "0" : "");
    amount = amount.replace("-", "");          // 부호는 분리해 콤마 계산에서 제외
    amount = amount.split(".");

    const amount1 = amount[0].split("").reverse();
    const amount2 = amount[1];

    let output = "";
    for (let i = 0; i <= amount1.length - 1; i++) {
        output = amount1[i] + output;
        if ((i + 1) % 3 == 0 && (amount1.length - 1) !== i) {
            output = "," + output;
        }
    }

    if (type == "dollar") {
        output = amount2 ? "$ " + output + "." + amount2 : "$ " + output;
    } else if (type == "won") {
        output = amount2 ? output + "." + amount2 + "원" : output + "원";
    } else if (amount2) {
        output = output + "." + amount2;
    }

    return (negativeSe ? "-" : "") + output;
};


/**
 * @method
 * @name formatNumber
 * @description 셋째자리마다 콤마를 추가해서 반환한다.
 * @param {String|Number} value 포멧터를 적용할 값
 * @returns {String} 포멧터가 적용된 문자열
 * @example
$c.num.formatNumber("12345677"); // "12,345,677"
$c.num.formatNumber(12345677); // "12,345,677"
$c.num.formatNumber(-12345677); // "-12,345,677"
 * @hidden N
 * @exception 
 */
scwin.formatNumber = function (value) {

    if (typeof $p == 'string') {
        value = $p;
        return WebSquare.util.setNumber(value);
    };

    return WebSquare.util.setNumber(value);
};


/**
 * @method
 * @name isNumber
 * @description 숫자가 맞는지 여부를 검사한다.
 * @param {String|Number} value 검사할 숫자 값
 * @returns {Boolean} 숫자이면 true, 아니면 false 반환
 * @example
$c.num.isNumber("123");   // true
$c.num.isNumber(123);     // true
$c.num.isNumber("-1.23"); // true
$c.num.isNumber("a123");  // false
 * @hidden N
 * @exception 
 */
scwin.isNumber = function (value) {
    return !isNaN(value);
};


/**
 * @method
 * @name isOdd
 * @description 홀수가 맞는지 여부를 검사한다.
 * @param {String|Number} value 검사할 값
 * @returns {Boolean} 홀수이면 true, 아니면 false 반환
 * @example
$c.num.isOdd("123"); // true;
$c.num.isOdd(123); // true;
$c.num.isOdd("122"); // false;
$c.num.isOdd(122); // false;
 * @hidden N
 * @exception 
 */
scwin.isOdd = function (value) {
    return WebSquare.util.isOdd(value);
};

/**
 * @method
 * @name parseInt
 * @description 문자열을 정수형으로 변환한다.
 * @param {String} value 정수 문자열 
 * @param {Number} defaultValue 결과가 NaN일때 반환할 기본 값
 * @return {Number} 변환된 정수형 값
 * @hidden N
 * @exception 
 * @example
$c.num.parseInt("5231"); // 5231;
 */
scwin.parseInt = function (value, defaultValue) {
    return WebSquare.util.parseInt(value, defaultValue);
};


/**
 * @method
 * @name parseFloat
 * @description 문자열을 실수형으로 변환한다.
 * @param {String} value 실수 문자열 
 * @param {Number} defaultValue 결과가 NaN일때 반환할 기본 값
 * @returns {Number} 변환된 실수형 값
 * @example
$c.num.parseFloat("5231.22"); // 5231.22;
 * @hidden N
 * @exception 
 */
scwin.parseFloat = function (value, defaultValue) {
    return WebSquare.util.parseFloat(value, defaultValue);
};


/**
 * @method
 * @name formatByte
 * @description 바이트 값을 적절한 단위(KB, MB, GB)를 변환해서 반환한다.
 * @param {String} value 변환할 값
 * @returns {String} 단위가 적용된 문자열
 * @example
$c.num.formatByte(32132); // "31.4 KB"
 * @hidden N
 * @exception
 */
scwin.formatByte = function (value) {
    const unitType = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB'];
    if (value == 0 || value == "0" || isNaN(value)) {
        return 0 + " " + unitType[0];
    }
    const index = Math.floor(Math.log(value) / Math.log(1024));
    return (value / Math.pow(1024, index)).toFixed(1) + " " + unitType[index];
};

// =============================================================================
// 추가 숫자 함수 (commonUtils.js 기준 정리)
// =============================================================================

/**
 * @method
 * @name unFormatMoney
 * @description 금액 포맷(콤마, $, 원)을 제거한 숫자를 반환한다.
 * @param {String} value 포맷이 적용된 금액 문자열
 * @returns {Number} 포맷이 제거된 숫자
 * @hidden N
 * @exception
 * @example
$c.num.unFormatMoney("12,345");   // 12345
$c.num.unFormatMoney("$12,345");  // 12345
$c.num.unFormatMoney("12,345원"); // 12345
 */
scwin.unFormatMoney = function (value) {
    return Number(String(value).replace(/[,$원]/g, "").trim());
};

/**
 * @method
 * @name unFormatNumber
 * @description 천단위 콤마를 제거한 숫자를 반환한다.
 * @param {String} value 콤마가 포함된 숫자 문자열
 * @returns {Number} 콤마가 제거된 숫자
 * @hidden N
 * @exception
 * @example
$c.num.unFormatNumber("12,345,677");  // 12345677
$c.num.unFormatNumber("-12,345,677"); // -12345677
 */
scwin.unFormatNumber = function (value) {
    return Number(String(value).replace(/,/g, ""));
};

/**
 * @method
 * @name isInteger
 * @description 정수 타입이 맞는지 여부를 검사한다.
 * @param {String|Number} value 검사할 값
 * @returns {Boolean} 정수이면 true, 아니면 false 반환
 * @hidden N
 * @exception
 * @example
$c.num.isInteger("123");   // true
$c.num.isInteger(123);     // true
$c.num.isInteger(123.123); // false
 */
scwin.isInteger = function (value) {
    return WebSquare.util.isInteger(value);
};

/**
 * @method
 * @name numberToKor
 * @description 숫자를 한글 수(영/일/이/…)로 변환한다.
 * @param {String|Number} num 변환할 숫자
 * @param {(String|Object)} opts 접미 문자열 또는 { firstFix, lastFix } 옵션
 * @returns {String} 한글로 변환된 문자열
 * @hidden N
 * @exception
 * @example
$c.num.numberToKor("12345");     // "일만이천삼백사십오"
$c.num.numberToKor(12345, "원"); // "일만이천삼백사십오원"
 */
scwin.numberToKor = function (num, opts) {
    if (typeof opts === "string") {
        opts = { firstFix: "", lastFix: opts };
    }

    num = parseInt((num + "").replace(/[^0-9]/g, ""), 10) + "";
    if (num === "0") {
        return ($c.util.isEmpty(opts?.firstFix) ? "" : opts.firstFix) + "영" + ($c.util.isEmpty(opts?.lastFix) ? "" : opts.lastFix);
    }

    const number = ["영", "일", "이", "삼", "사", "오", "육", "칠", "팔", "구"];
    const unit = ["", "만", "억", "조", "경"];
    const smalUnit = ["천", "백", "십", ""];
    const unitCnt = Math.ceil(num.length / 4);
    num = num.padStart(unitCnt * 4, "0");
    const array = num.match(/[\w\W]{4}/g);

    function makeHan(text) {
        let str = "";
        for (let i = 0; i < text.length; i++) {
            const n = text[i];
            if (n === "0") {
                continue;
            }
            str += number[n] + smalUnit[i];
        }
        return str;
    }

    const result = [];
    for (let i = array.length - 1, u = 0; i >= 0; i--, u++) {
        const hanValue = makeHan(array[i]);
        if (hanValue === "") {
            continue;
        }
        result.unshift(hanValue + unit[u]);
    }

    return ($c.util.isEmpty(opts?.firstFix) ? "" : opts.firstFix) + result.join("") + ($c.util.isEmpty(opts?.lastFix) ? "" : opts.lastFix);
};

/**
 * @method
 * @name formatNumberKor
 * @description 숫자를 한글 금액명으로 변환한다. (소수/접두·접미 옵션 지원)
 * @param {String|Number} number 변환할 숫자
 * @param {(String|Object)} opts 접미 문자열 또는 { firstFix, lastFix, noNum, dotTxt, negativeSe } 옵션
 * @returns {String} 한글 금액명 문자열
 * @hidden N
 * @exception
 * @example
$c.num.formatNumberKor("12345677");      // "일천이백삼십사만오천육백칠십칠"
$c.num.formatNumberKor(-12345677, "원"); // "일천이백삼십사만오천육백칠십칠원"
 */
scwin.formatNumberKor = function (number, opts) {
    let options;
    if (typeof opts === "string") {
        options = { firstFix: "", lastFix: opts, noNum: true, dotTxt: "점", negativeSe: false };
    } else {
        options = Object.assign({ firstFix: "", lastFix: "", noNum: true, dotTxt: "점", negativeSe: false }, opts);
    }

    if (!$c.num.isNumber(number) || String(number).trim() === "") {
        console.log("숫자가 아닌값이 들어 있습니다=>", number);
        return "";
    }

    const negativeSe = options.negativeSe && number < 0;
    number = Math.abs(number);
    const decimalKor = ["십", "전", "리"];
    const danUnitsKor1 = [null, "십", "백", "천"];
    const danUnitsKor2 = ["", "만", "억", "조", "경", "해", "자"];
    const numberKor = ["영", "일", "이", "삼", "사", "오", "육", "칠", "팔", "구"];

    const danTxt = String(number).split(".")[0];
    const decTxt = String(number).split(".")[1];
    let digit = danTxt.length - 1;
    let result = "";
    for (let idx = 0, zero = 0; idx < danTxt.length; idx++, digit--) {
        if (danTxt.charAt(idx) === "0") {
            zero++;
            result += (digit % 4 === 0 && zero < 4) ? danUnitsKor2[Math.floor(digit / 4)] : "";
        } else {
            zero = 0;
            result += numberKor[Number(danTxt.charAt(idx))] + (danUnitsKor1[digit % 4] || danUnitsKor2[Math.floor(digit / 4)]);
        }
    }
    result = (negativeSe ? "-" : "") + ((result === "") ? result : (options.firstFix || "") + result + (options.lastFix || ""));

    if (!$c.util.isEmpty(decTxt)) {
        if (options.noNum) {
            result += (((options.lastFix || "") === "") && result !== "") ? "원" : "";
            for (let idx = 0; idx < decTxt.length && idx <= 2; idx++) {
                result = (decTxt.charAt(idx) === "0") ? result : result + numberKor[Number(decTxt.charAt(idx))] + decimalKor[idx];
            }
            if (decTxt.length < 2) {
                result += "전";
            }
        } else {
            result += (((options.lastFix || "") === "") && result !== "") ? options.dotTxt : "";
            for (let idx = 0; idx < decTxt.length; idx++) {
                result += numberKor[Number(decTxt.charAt(idx))];
            }
        }
    }
    return result;
};

/**
 * @method
 * @name humanFileSize
 * @description 바이트 값을 사람이 읽기 쉬운 단위 문자열로 변환한다.
 * @param {Number} bytes 바이트 값
 * @param {Boolean} si true=SI(1000, KB), false=2진(1024, KiB) (기본값 true)
 * @param {Number} dp 소수점 자리수 (기본값 1)
 * @returns {String} 변환된 문자열
 * @hidden N
 * @exception
 * @example
$c.num.humanFileSize(5000);        // "5.0 KB"
$c.num.humanFileSize(5000, false); // "4.9 KiB"
 */
scwin.humanFileSize = function (bytes, si, dp) {
    if ($c.util.isEmpty(bytes)) {
        bytes = 0;
    }
    si = (si !== false);                              // 기본값 true
    dp = (typeof dp === "undefined") ? 1 : dp;        // 기본값 1

    const thresh = si ? 1000 : 1024;
    if (Math.abs(bytes) < thresh) {
        return bytes + " B";
    }

    const units = si
        ? ["KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"]
        : ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"];
    let u = -1;
    const r = Math.pow(10, dp);

    do {
        bytes /= thresh;
        ++u;
    } while (Math.round(Math.abs(bytes) * r) / r >= thresh && u < units.length - 1);

    return bytes.toFixed(dp) + " " + units[u];
};
